import * as product from "../src/value.mjs";
const name = process.argv[2] ?? "value";
const expected = name === "label" ? "two" : 2;
if (product[name] === expected) console.log(name + " is " + expected);
else {
  console.log("expected " + expected + ", got " + product[name]);
  process.exitCode = 1;
}
